function facts(s){return [['Shipment',s.shipment_number],['Mode / direction',`${s.mode} · ${s.direction||'—'}`],['Master reference',s.master_reference],['House reference',s.house_reference],['Booking',s.booking_reference],['Origin',s.origin_code||s.origin_name],['Destination',s.destination_code||s.destination_name],['Pieces',s.pieces],['Gross weight',s.weight==null?'':`${s.weight} ${s.weight_unit||'KG'}`],['Volume',s.volume_cbm==null?'':`${s.volume_cbm} CBM`],['ETD',s.etd?new Date(s.etd).toLocaleString():null],['ETA',s.eta?new Date(s.eta).toLocaleString():null]].filter(([,v])=>v!==null&&v!==undefined&&v!=='')}

async function draft(doc,s){if(doc.sourceManaged)throw new Error('Approved Shipping Instructions are finalized from the Instructions workspace after customer submission and operator approval.');const{data:approved}=await supabase.from('instruction_submissions').select('id,instruction_requests!inner(source_type,source_id,status)').eq('review_status','APPROVED').eq('instruction_requests.source_type','SHIPMENT').eq('instruction_requests.source_id',s.id).order('reviewed_at',{ascending:false}).limit(1).maybeSingle();const snapshot={shipment_number:s.shipment_number,mode:s.mode,direction:s.direction,master_reference:s.master_reference,house_reference:s.house_reference,booking_reference:s.booking_reference,origin:s.origin_code||s.origin_name,destination:s.destination_code||s.destination_name,pieces:s.pieces,weight:s.weight,weight_unit:s.weight_unit,volume_cbm:s.volume_cbm,generated_at:new Date().toISOString()};const{data,error}=await supabase.from('shipment_document_issues').insert({organization_id:s.organization_id,shipment_id:s.id,document_code:doc.code,document_scope:doc.scope,status:'DRAFT',data_snapshot:snapshot,source_instruction_submission_id:approved?.id||null}).select().single();if(error)throw error;return data}

function printAirWaybill(doc,s,issue){const x=issue?.data_snapshot||s;const w=window.open('','_blank');if(!w)return alert('Allow pop-ups to preview this document.');const house=doc.code==='HAWB',num=house?(x.house_reference||s.house_reference||s.shipment_number):(x.master_reference||s.master_reference||s.shipment_number),shipper=x.shipper||s.shipper_name||'Shipper name / address required',consignee=x.consignee||s.consignee_name||'Consignee name / address required',origin=x.origin||s.origin_code||s.origin_name||'—',dest=x.destination||s.destination_code||s.destination_name||'—';w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(doc.label)} · ${esc(num)}</title><style>@page{size:letter;margin:.22in}*{box-sizing:border-box}body{font:8px Arial;color:#111;margin:0}.bar{display:flex;justify-content:space-between;align-items:end;margin-bottom:4px}.brand{font-size:15px;font-weight:900;letter-spacing:3px}.awbno{font:700 14px monospace}.awb{border:1.4px solid #111}.row{display:grid;border-bottom:1px solid #111}.r2{grid-template-columns:1fr 1fr}.r3{grid-template-columns:1fr 1fr 1fr}.r4{grid-template-columns:1fr 1fr 1fr 1fr}.cell{min-height:48px;padding:4px 5px;border-right:1px solid #111}.cell:last-child{border-right:0}.cell label{display:block;font-size:6.5px;margin-bottom:4px}.cell b{font-size:9px;white-space:pre-line}.title{text-align:center;font-size:17px}.contract{font-size:7px;line-height:1.25}.route{grid-template-columns:1.2fr .7fr .7fr .7fr .7fr}.cargohead,.cargo{display:grid;grid-template-columns:.45fr .7fr .35fr .65fr .8fr .55fr .7fr 1.8fr}.cargohead>div,.cargo>div{padding:4px;border-right:1px solid #111}.cargohead{border-bottom:1px solid #111;text-align:center;font-size:6.5px}.cargo{min-height:235px}.cargo>div{font-size:9px}.cert{min-height:95px}.sign{display:grid;grid-template-columns:1fr 1fr;margin-top:40px;gap:35px}.sign span{border-top:1px solid #111;text-align:center;padding-top:3px}.foot{display:flex;justify-content:space-between;padding:5px;font-weight:700}.draft{position:fixed;top:45%;left:25%;transform:rotate(-28deg);font-size:70px;font-weight:900;color:rgba(0,0,0,.055);pointer-events:none}.terms-page{page-break-before:always;font-size:8px;line-height:1.4;padding:8px}.terms-page h2{text-align:center;font-size:14px}.terms-cols{columns:2;column-gap:24px;text-align:justify}.notice{font-weight:700;border-bottom:1px solid #111;padding-bottom:7px;margin-bottom:8px}@media print{button{display:none}}</style></head><body><button onclick="print()">Print / Save PDF</button><div class="draft">DRAFT</div><div class="bar"><div><div class="brand">NODARA</div><small>${house?'HOUSE AIR WAYBILL':'MASTER AWB WORKING COPY'}</small></div><div class="awbno">${esc(num)}</div></div><div class="awb"><div class="row r2"><div class="cell"><label>Shipper's Name and Address</label><b>${esc(shipper)}\n${esc(s.shipper_address||'')}</b></div><div class="cell"><label>Not Negotiable</label><div class="title">Air Waybill</div><b>Issued by ${esc(x.issuing_agent||'Issuing agent / office required')}</b></div></div><div class="row r2"><div class="cell"><label>Consignee's Name and Address</label><b>${esc(consignee)}\n${esc(s.consignee_address||'')}</b></div><div class="cell contract">Goods are accepted for carriage subject to the applicable conditions of contract and carrier rules. Review the reverse conditions before issue. Declared values, routing, handling and regulatory statements form part of this document when completed.</div></div><div class="row r2"><div class="cell"><label>Issuing Carrier's Agent Name and City</label><b>${esc(x.issuing_agent||'Issuing agent / office required')}</b></div><div class="cell"><label>Accounting Information</label><b>${esc(x.accounting_info||s.reference||'')}</b></div></div><div class="row route"><div class="cell"><label>Airport of Departure / Requested Routing</label><b>${esc(origin)}</b></div><div class="cell"><label>To</label><b>${esc(dest)}</b></div><div class="cell"><label>By First Carrier</label><b>${esc(x.first_carrier||'—')}</b></div><div class="cell"><label>Currency</label><b>${esc(x.currency||'USD')}</b></div><div class="cell"><label>Charges</label><b>${esc((x.wt_val||'PPD')+' / '+(x.other_ppd_coll||'PPD'))}</b></div></div><div class="row r4"><div class="cell"><label>Airport of Destination</label><b>${esc(dest)}</b></div><div class="cell"><label>Requested Flight / Date</label><b>${esc(x.flight_1||'—')} / ${esc(x.flight_date||(s.etd?new Date(s.etd).toLocaleDateString():'—'))}</b></div><div class="cell"><label>Declared Value for Carriage</label><b>${esc(x.declared_carriage||'NVD')}</b></div><div class="cell"><label>Declared Value for Customs</label><b>${esc(x.declared_customs||'NCV')}</b></div></div><div class="row"><div class="cell"><label>Handling Information / Special Instructions</label><b>${esc(x.handling||x.remarks||s.notes||'')}</b></div></div><div class="cargohead"><div>No. Pieces</div><div>Gross Weight</div><div>kg/lb</div><div>Rate Class</div><div>Chargeable Weight</div><div>Rate</div><div>Total</div><div>Nature and Quantity of Goods (incl. dimensions / volume)</div></div><div class="cargo"><div>${esc(x.pieces??s.pieces??'')}</div><div>${esc(x.weight??s.weight??'')}</div><div>${esc(x.weight_unit||s.weight_unit||'KG')}</div><div></div><div>${esc(x.rate_class||'')}</div><div>${esc(x.chargeable_weight||'')}</div><div>${esc(x.rate_charge||'')}</div><div>${esc(x.cargo_total||'')}</div><div>${esc(x.volume_cbm!=null?x.volume_cbm+' CBM':s.volume_cbm!=null?s.volume_cbm+' CBM':'')}<br><br>${esc(x.cargo_description||'')}<br>${esc(x.dimensions||'')}<br>${(Array.isArray(x.cargo_detail_lines)?x.cargo_detail_lines:[]).map(v=>esc(v)).join('<br>')}<br>${esc(x.aes_itn||'')}<br>${esc(x.remarks||'')}</div></div><div class="row r2"><div class="cell"><label>Charges</label><b>Weight Charge<br><br>Valuation Charge<br><br>Tax<br><br>Other Charges</b></div><div class="cell cert"><label>Shipper Certification</label><p>The shipper or its agent certifies that the particulars supplied for this shipment are correct and that any dangerous goods are properly described, packed, marked, labeled and documented as required by applicable regulations.</p><div class="sign"><span>Signature of Shipper or Agent</span><span>Date</span></div></div></div><div class="foot"><span>DRAFT · R${issue.revision} · ${esc(issue.id)}</span><span>${esc(num)}</span></div></div>${house?'<section class="terms-page"><h2>Conditions of Contract</h2><div class="notice">Use the organization-approved conditions of carriage before issuing this HAWB. The final legal terms must be version-controlled separately from shipment data.</div><div class="terms-cols"><p>Carriage is subject to applicable international conventions, laws, government regulations, tariffs and the issuing forwarder or carrier conditions of carriage. Liability limitations, claims periods, routing rights, payment obligations and shipper compliance responsibilities must be stated in the approved terms configured for the issuing organization.</p><p>The shipper is responsible for accurate cargo particulars and for furnishing documents and information necessary for lawful packing, carriage, export, import and delivery. Dangerous goods require the applicable declarations and compliance evidence.</p><p>This draft intentionally does not substitute generic wording for the issuing organization\'s approved contract terms. Once approved terms are configured, NODARA will freeze the applicable terms version with the issued document revision.</p></div></section>':''}</body></html>`);w.document.close()}

function printDoc(doc,s,issue){if(['HAWB','MAWB_DATA'].includes(doc.code))return printAirWaybill(doc,s,issue);const w=window.open('','_blank');if(!w)return alert('Allow pop-ups to preview this document.');const warning=doc.carrier?'WORKING COPY — carrier-issued master document remains authoritative.':doc.controlled?'CONTROLLED DOCUMENT — complete required declarations, approvals and signatures before issue.':'';w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(doc.label)} · ${esc(s.shipment_number)}</title><style>@page{size:letter;margin:.45in}*{box-sizing:border-box}body{font:11px Arial;color:#111;margin:0}header{display:flex;justify-content:space-between;border-bottom:3px solid #111;padding-bottom:12px}h1{font-size:22px;margin:4px 0}.brand{font-weight:900;letter-spacing:3px;font-size:17px}.tag{font-size:8px;letter-spacing:1.5px}.warn{margin:14px 0;padding:9px;border:1px solid #111;font-weight:700}.grid{display:grid;grid-template-columns:180px 1fr;border:1px solid #999;margin-top:18px}.grid div{padding:9px;border-bottom:1px solid #ccc}.grid div:nth-child(odd){font-weight:700;background:#f5f5f5}.terms{margin-top:22px;border-top:1px solid #999;padding-top:12px;font-size:9px;line-height:1.45}.sign{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:38px}.sign div{border-top:1px solid #111;padding-top:5px}.foot{margin-top:25px;font-size:8px;color:#555}@media print{button{display:none}}</style></head><body><button onclick="print()">Print / Save PDF</button><header><div><div class="brand">NODARA</div><div class="tag">SHIPMENT DOCUMENT CONTROL</div></div><div style="text-align:right"><div class="tag">${esc(doc.code)} · DRAFT R${issue.revision}</div><h1>${esc(doc.label)}</h1><b>${esc(s.shipment_number)}</b></div></header>${warning?`<div class="warn">${esc(warning)}</div>`:''}<div class="grid">${facts(s).map(([k,v])=>`<div>${esc(k)}</div><div>${esc(v)}</div>`).join('')}</div>${doc.terms?'<div class="terms"><b>Terms and conditions</b><br>Organization-approved terms must be configured before this document is issued. The shipment data and document revision are controlled separately from the terms template.</div>':''}<div class="sign"><div>Prepared / authorized by</div><div>Date / signature</div></div><div class="foot">Draft generated from NODARA · Document instance ${esc(issue.id)} · Review all carrier, security, dangerous-goods and jurisdiction-specific requirements before issue.</div></body></html>`);w.document.close()}


async function ensurePdfTools(){if(!window.html2canvas)await new Promise((r,j)=>{const x=document.createElement('script');x.src='https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js';x.onload=r;x.onerror=j;document.head.appendChild(x)});if(!window.jspdf?.jsPDF)await new Promise((r,j)=>{const x=document.createElement('script');x.src='https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';x.onload=r;x.onerror=j;document.head.appendChild(x)});return window.jspdf.jsPDF}
async function generatedPdfFile(host,doc,s,issue,state){await ensurePdfTools();let paper=host.querySelector('.nds-paper'),temp=null;if(!paper){temp=document.createElement('div');temp.innerHTML=studioPage(doc,s,state);paper=temp.firstElementChild}if(!paper)throw new Error('Document page is not available.');const clone=paper.cloneNode(true);clone.querySelectorAll('[contenteditable]').forEach(x=>x.removeAttribute('contenteditable'));clone.querySelectorAll('.nds-smartline-tools,button').forEach(x=>x.remove());const wrap=document.createElement('div');wrap.style.cssText='position:fixed;left:-12000px;top:0;width:920px;background:#fff;padding:0;z-index:-1';wrap.appendChild(clone);document.body.appendChild(wrap);try{const canvas=await window.html2canvas(clone,{scale:2,backgroundColor:'#ffffff',useCORS:true,logging:false}),JS=window.jspdf.jsPDF,pdf=new JS({orientation:'portrait',unit:'pt',format:'letter'}),pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),margin=18,scale=Math.min((pw-margin*2)/canvas.width,(ph-margin*2)/canvas.height);pdf.addImage(canvas.toDataURL('image/jpeg',.96),'JPEG',(pw-canvas.width*scale)/2,margin,canvas.width*scale,canvas.height*scale,'','FAST');const safe=String((doc.code==='HAWB'?state.house_reference:state.master_reference)||s.shipment_number||'document').replace(/[^a-zA-Z0-9._-]/g,'_');return new File([pdf.output('blob')],doc.code+'_'+safe+'_R'+issue.revision+'.pdf',{type:'application/pdf'})}finally{wrap.remove()}}
async function storeGeneratedPdf(file,doc,s,issue,state){const{data:tx,error:te}=await supabase.from('transactions').select('id,organization_id').eq('transaction_type','SHIPMENT').eq('domain_record_id',s.id).maybeSingle();if(te)throw te;if(!tx)throw new Error('Shipment transaction context is unavailable.');const path=tx.organization_id+'/generated/shipments/'+s.id+'/'+issue.id+'/'+file.name,{error:up}=await supabase.storage.from('nodara-documents').upload(path,file,{contentType:'application/pdf',upsert:false});if(up)throw up;const payload={organization_id:tx.organization_id,transaction_id:tx.id,document_type:doc.code,storage_path:path,file_name:file.name,mime_type:'application/pdf',display_name:doc.label+' · R'+issue.revision,document_number:doc.code==='HAWB'?state.house_reference:state.master_reference,version_no:issue.revision,is_current:true,category:'SHIPPING',source:'GENERATED',status:'ACTIVE',metadata:{shipment_id:s.id,shipment_document_issue_id:issue.id,document_code:doc.code,revision:issue.revision,generated_from:'SHIPMENT_DOCUMENT_STUDIO'},provenance:{capture_source:'GENERATED',surface:'SHIPMENT_DOCUMENT_STUDIO',shipment_id:s.id,issue_id:issue.id}};const{data:d,error}=await supabase.from('documents').insert(payload).select().single();if(error){await supabase.storage.from('nodara-documents').remove([path]);throw error}const{error:le}=await supabase.from('document_links').insert({organization_id:tx.organization_id,document_id:d.id,transaction_id:tx.id,context_type:'SHIPMENT',context_id:s.id,context_reference:s.shipment_number,link_role:'GENERATED',is_primary:true,provenance:{surface:'SHIPMENT_DOCUMENT_STUDIO',issue_id:issue.id}});if(le){await supabase.from('documents').delete().eq('id',d.id);await supabase.storage.from('nodara-documents').remove([path]);throw le}await supabase.from('document_activity').insert({organization_id:tx.organization_id,document_id:d.id,action:'GENERATED',detail:{shipment_id:s.id,document_code:doc.code,revision:issue.revision}});return d}
async function generateAndStorePdf(host,doc,s,issue,state){await saveStudioIssue(issue,state);const file=await generatedPdfFile(host,doc,s,issue,state);return storeGeneratedPdf(file,doc,s,issue,state)}

