async function hydrateAwbParties(s,state){try{const{data:tx}=await supabase.from('transactions').select('id,organization_id').eq('transaction_type','SHIPMENT').eq('domain_record_id',s.id).maybeSingle();if(!tx)return state;const{data:ps}=await supabase.from('transaction_parties').select('role_code,party_name_snapshot,entity_id,address_id').eq('transaction_id',tx.id).eq('is_primary',true);const format=async p=>{if(!p)return'';let name=p.party_name_snapshot||'';if(p.entity_id){const{data:e}=await supabase.from('entities').select('name').eq('id',p.entity_id).maybeSingle();name=e?.name||name;let aq=supabase.from('entity_addresses').select('line1,line2,city,state_region,postal_code,country_code,formatted_address').eq('entity_id',p.entity_id).eq('active',true).order('is_primary',{ascending:false}).limit(1);const{data:a}=await aq;const x=a?.[0];if(x){const addr=x.formatted_address||[x.line1,x.line2,[x.city,x.state_region,x.postal_code].filter(Boolean).join(' '),x.country_code].filter(Boolean).join('\n');return[name,addr].filter(Boolean).join('\n')}}return name};for(const [role,key] of [['SHIPPER','shipper'],['CONSIGNEE','consignee'],['ISSUING_PARTY','issuing_agent']])if(!state[key])state[key]=await format((ps||[]).find(x=>x.role_code===role));if(!state.issuing_agent){const{data:o}=await supabase.from('organizations').select('name').eq('id',tx.organization_id).maybeSingle();state.issuing_agent=o?.name||''}return state}catch(e){console.warn('AWB party hydration',e);return state}}
async function hydrateAwbBooking(s,state){try{const{data:b,error}=await supabase.from('shipment_air_bookings').select('*').eq('shipment_id',s.id).maybeSingle();if(error)throw error;if(!b)return state;const put=(k,v)=>{if((state[k]===null||state[k]===undefined||state[k]==='')&&v!==null&&v!==undefined&&v!=='')state[k]=v},own=(k,v)=>{if(v!==null&&v!==undefined&&v!=='')state[k]=v};/* Booking is source of truth for carrier identity/routing. Never let an older document snapshot override it. */own('master_reference',b.mawb_number);own('booking_reference',b.booking_reference);own('origin',b.origin_code);own('destination',b.destination_code);own('first_carrier',b.carrier_name);own('flight_1',b.flight_number);own('flight_date',b.etd?new Date(b.etd).toLocaleDateString():null);own('etd',b.etd);own('eta',b.eta);const legs=Array.isArray(b.routing_legs)?b.routing_legs:[];own('route_1',legs[0]?.code||legs[0]?.airport||legs[0]);own('route_2',legs[1]?.code||legs[1]?.airport||legs[1]);return state}catch(e){console.warn('AWB booking hydration',e);return state}}
async function hydrateAwbCargo(s,state){try{const{data,error}=await supabase.from('cargo_assignments').select('cargo_objects(quantity,length,width,height,dimension_unit,description,part_number,calculated_volume_cbm)').eq('transaction_type','SHIPMENT').eq('transaction_id',s.id).neq('status','REMOVED');if(error)throw error;const rows=(data||[]).map(r=>r.cargo_objects).filter(Boolean),dims=[],descs=[];for(const x of rows){if(x.description||x.part_number)descs.push(x.description||x.part_number);if(x.length&&x.width&&x.height){const n=Number(x.quantity||1),unit=String(x.dimension_unit||'IN').toUpperCase();dims.push([x.length,x.width,x.height].join(' × ')+' '+unit+' × '+n)}}if(!state.cargo_description&&descs.length)state.cargo_description=[...new Set(descs)].join(' / ');if(!state.dimensions&&dims.length)state.dimensions=dims.join('\n');if(!Array.isArray(state.cargo_detail_lines))state.cargo_detail_lines=[];for(const d of dims)if(!state.cargo_detail_lines.includes(d))state.cargo_detail_lines.push(d)}catch(e){console.warn('AWB cargo hydration',e)}return state}
function studioSeed(s,issue){const x=issue?.data_snapshot||{},v=(k,f='')=>x[k]??s[k]??f;return{...x,shipment_number:v('shipment_number'),master_reference:v('master_reference'),house_reference:v('house_reference'),booking_reference:v('booking_reference'),origin:x.origin??s.origin_code??s.origin_name??'',destination:x.destination??s.destination_code??s.destination_name??'',pieces:v('pieces'),weight:v('weight'),weight_unit:v('weight_unit','KG'),volume_cbm:v('volume_cbm'),shipper:x.shipper??s.shipper_name??'',consignee:x.consignee??s.consignee_name??'',shipper_account:v('shipper_account'),consignee_account:v('consignee_account'),issuing_agent:v('issuing_agent'),agent_iata:v('agent_iata'),agent_account:v('agent_account'),accounting_info:x.accounting_info??s.reference??'',first_carrier:v('first_carrier'),route_1:v('route_1'),carrier_2:v('carrier_2'),route_2:v('route_2'),carrier_3:v('carrier_3'),flight_1:v('flight_1'),etd:v('etd'),eta:v('eta'),flight_date:x.flight_date??(s.etd?new Date(s.etd).toLocaleDateString():''),currency:v('currency','USD'),charges_code:v('charges_code'),wt_val:v('wt_val','PPD'),other_ppd_coll:v('other_ppd_coll','PPD'),declared_carriage:v('declared_carriage','NVD'),declared_customs:v('declared_customs','NCV'),insurance:v('insurance'),handling:x.handling??s.notes??'',aes_itn:v('aes_itn'),sci:v('sci'),cargo_description:v('cargo_description'),cargo_detail_lines:Array.isArray(x.cargo_detail_lines)?x.cargo_detail_lines:[],dimensions:x.dimensions??(s.volume_cbm!=null?s.volume_cbm+' CBM':''),rate_class:v('rate_class'),chargeable_weight:v('chargeable_weight'),rate_charge:v('rate_charge'),cargo_total:v('cargo_total'),weight_charge:v('weight_charge'),valuation_charge:v('valuation_charge'),tax:v('tax'),other_agent:v('other_agent'),other_carrier:v('other_carrier'),other_charges:v('other_charges'),total_prepaid:v('total_prepaid'),total_collect:v('total_collect'),conversion_rate:v('conversion_rate'),destination_cc:v('destination_cc'),destination_charges:v('destination_charges'),collect_total:v('collect_total'),authorized_agent:v('authorized_agent'),execution_place:v('execution_place'),execution_date:v('execution_date'),remarks:x.remarks??s.notes??''}}
