export async function openStudio(host,doc,s,issue=null){if(!issue)issue=await draft(doc,s);let state=studioSeed(s,issue);if(['HAWB','MAWB_DATA'].includes(doc.code)){state=await hydrateAwbBooking(s,state);state=await hydrateAwbParties(s,state);state=await hydrateAwbCargo(s,state);}let history=[structuredClone(state)],cursor=0,dirty=false,view='document';const groups=[['booking','AWB & Booking','Carrier booking and document references'],['parties','Parties & Accounts','Canonical shipment parties and issuing office'],['routing','Routing & Flight','Physical routing inherited from Booking'],['charges','Charges & Declared Values','AWB payment and valuation declarations'],['handling','Handling & Regulatory','Handling, SCI and export filing statements'],['cargo','Cargo & Rating','Cargo-derived totals plus AWB rating detail'],['rating','Charge Calculation','Amounts printed in the accounting section'],['execution','Execution','Authorization and issue details']],longFields=new Set(['shipper','consignee','issuing_agent','accounting_info','handling','aes_itn','cargo_description','dimensions','remarks']);const fieldControl=([k,l,src])=>`<label class="nds-form-field ${longFields.has(k)?'wide':''} ${['BOOKING','PARTIES','CARGO','SHIPMENT','HOUSE'].includes(src)?'sourced':''}"><span><b>${esc(l)}</b><i>${esc(src)}</i></span>${longFields.has(k)?`<textarea data-field-input="${k}">${esc(state[k]??'')}</textarea>`:`<input data-field-input="${k}" value="${esc(state[k]??'')}">`}<small>${src==='BOOKING'?'From Booking · document override only':src==='PARTIES'?'From Shipment Parties · document override only':src==='CARGO'?'From Shipment Cargo · document override only':src==='SHIPMENT'||src==='HOUSE'?'From Shipment record · document override only':'Document field'}</small></label>`;const fieldsView=()=>`<div class="nds-fields-view nds-fields-v3"><div class="nds-fields-head"><div><small>AWB STRUCTURED EDITOR</small><h3>Air Waybill fields</h3><p>Operational data already completed elsewhere is pulled in automatically. Edit here only when this AWB needs an override.</p></div><div class="nds-field-legend"><span><i class="canonical"></i>Canonical source</span><span><i class="document"></i>Document-only</span></div></div><nav class="nds-group-nav">${groups.map(([id,label])=>`<button data-group-jump="${id}">${label}</button>`).join('')}</nav><div class="nds-field-groups">${groups.map(([id,label,help])=>{const rows=STUDIO_FIELDS.filter(x=>x[3]===id&&x[0]!=='cargo_detail_lines');return `<section class="nds-field-group" data-field-group="${id}"><header><div><small>${esc(id.toUpperCase())}</small><h4>${esc(label)}</h4></div><p>${esc(help)}</p></header><div class="nds-fields-grid">${rows.map(fieldControl).join('')}</div>${id==='cargo'?'<div class="nds-cargo-lines-summary"><span>Nature & Quantity rows</span><b>'+esc((state.cargo_detail_lines||[]).length)+' custom / derived rows</b><small>Use Document view to arrange individual printed rows.</small></div>':''}</section>`}).join('')}</div></div>`;const render=()=>{host.innerHTML=`<div class="nds-shell"><div class="nds-toolbar"><button class="subtle" data-nds-back>← Documents</button><div><small>${esc(doc.group)} · ${esc(doc.scope)}</small><b>${esc(doc.label)}</b><span data-nds-status>DRAFT R${esc(issue.revision)} · Saved</span></div><div class="nds-view-toggle"><button class="${view==='fields'?'active':''}" data-nds-view="fields">Fields</button><button class="${view==='document'?'active':''}" data-nds-view="document">Document</button></div><div class="nds-tools"><button class="subtle" data-nds-undo disabled>↶</button><button class="subtle" data-nds-redo disabled>↷</button><button class="secondary" data-nds-preview>Preview PDF</button><button class="primary" data-nds-generate>Generate & Save PDF</button><button class="secondary" data-nds-save>Save draft</button></div></div><div class="nds-workspace ${view==='fields'?'fields-mode':''}"><div class="nds-canvas">${view==='fields'?fieldsView():studioPage(doc,s,state)}</div><aside class="nds-inspector"><small>CLICK A FIELD</small><h3>Edit directly on the document</h3><p>Click any highlighted value and type. Tab moves to the next field.</p><div data-nds-context><span>Source</span><b>—</b><small>Document edits are saved to this draft unless you explicitly update the Shipment.</small></div></aside></div></div>`;bind()};const push=()=>{history=history.slice(0,cursor+1);history.push(structuredClone(state));cursor++;dirty=true;buttons()};const buttons=()=>{const u=host.querySelector('[data-nds-undo]'),r=host.querySelector('[data-nds-redo]'),st=host.querySelector('[data-nds-status]');if(u)u.disabled=cursor<=0;if(r)r.disabled=cursor>=history.length-1;if(st)st.textContent=`DRAFT R${issue.revision} · ${dirty?'Unsaved changes':'Saved'}`};const bind=()=>{host.querySelectorAll('[data-nds-view]').forEach(b=>{if(b.dataset.ndsView==='document')b.title='Read-only AWB preview — edit values in Fields'});host.querySelectorAll('[data-group-jump]').forEach(b=>b.onclick=()=>host.querySelector(`[data-field-group="${b.dataset.groupJump}"]`)?.scrollIntoView({behavior:'smooth',block:'start'}));host.querySelectorAll('[data-nds-view]').forEach(b=>b.onclick=()=>{view=b.dataset.ndsView;render()});host.querySelectorAll('[data-field-input]').forEach(el=>el.oninput=()=>{state[el.dataset.fieldInput]=el.value;dirty=true;buttons()});const smart=host.querySelector('[data-awb-smartlines]');if(smart){const lines=Array.isArray(state.cargo_detail_lines)?state.cargo_detail_lines:[];smart.innerHTML='<div class="nds-smartline-tools"><textarea data-smart-paste placeholder="Paste cargo details, dimensions, AES/ITNs or remarks…"></textarea><button type="button" data-smart-organize>Organize lines</button><button type="button" data-smart-add>+ Add row</button></div><div data-smart-list></div>';const list=smart.querySelector('[data-smart-list]');const draw=()=>{list.innerHTML=lines.map((x,i)=>'<div class="nds-smart-row"><span contenteditable="true" data-smart-i="'+i+'">'+esc(x)+'</span><button type="button" data-smart-remove="'+i+'">×</button></div>').join('');list.querySelectorAll('[data-smart-i]').forEach(el=>el.oninput=()=>{lines[Number(el.dataset.smartI)]=el.innerText;state.cargo_detail_lines=lines;dirty=true;buttons()});list.querySelectorAll('[data-smart-remove]').forEach(b=>b.onclick=()=>{lines.splice(Number(b.dataset.smartRemove),1);state.cargo_detail_lines=lines;dirty=true;draw();buttons()})};draw();smart.querySelector('[data-smart-add]').onclick=()=>{lines.push('');state.cargo_detail_lines=lines;draw();list.lastElementChild?.querySelector('span')?.focus()};smart.querySelector('[data-smart-organize]').onclick=()=>{const raw=smart.querySelector('[data-smart-paste]').value.trim();if(!raw)return;const parsed=raw.split(/\n+/).map(x=>x.trim()).filter(Boolean);for(const line of parsed){const chunks=line.split(/\s{2,}|\s*\|\s*|;\s*/).map(x=>x.trim()).filter(Boolean);lines.push(...chunks)}state.cargo_detail_lines=lines;smart.querySelector('[data-smart-paste]').value='';dirty=true;draw();buttons()}}
host.querySelector('[data-nds-back]').onclick=()=>mountShipmentDocumentStudio(host,s);host.querySelector('[data-nds-save]').onclick=async e=>{e.currentTarget.disabled=true;try{issue=await saveStudioIssue(issue,state);dirty=false;buttons()}catch(err){alert(err.message)}finally{e.currentTarget.disabled=false}};host.querySelector('[data-nds-preview]').onclick=()=>printDoc(doc,{...s,...state},issue);host.querySelector('[data-nds-generate]').onclick=async e=>{const b=e.currentTarget,old=b.textContent;b.disabled=true;b.textContent='Generating PDF…';try{const d=await generateAndStorePdf(host,doc,s,issue,state);dirty=false;buttons();b.textContent='PDF saved ✓';const{data:u,error}=await supabase.storage.from('nodara-documents').createSignedUrl(d.storage_path,600);if(error)throw error;window.open(u.signedUrl,'_blank');setTimeout(()=>b.textContent=old,1800)}catch(err){alert(err.message);b.textContent=old}finally{b.disabled=false}};host.querySelector('[data-nds-undo]').onclick=()=>{if(cursor<=0)return;cursor--;state=structuredClone(history[cursor]);render()};host.querySelector('[data-nds-redo]').onclick=()=>{if(cursor>=history.length-1)return;cursor++;state=structuredClone(history[cursor]);render()};const fields=[...host.querySelectorAll('[data-nds-field]')];fields.forEach((el,idx)=>{const key=el.dataset.ndsField,meta=STUDIO_FIELDS.find(x=>x[0]===key),editable=el.querySelector('[contenteditable]');el.onclick=()=>{fields.forEach(x=>x.classList.toggle('active',x===el));const box=host.querySelector('[data-nds-context]');box.innerHTML=`<span>Source</span><b>${esc(meta?.[2]||'DOCUMENT')}</b><small>${meta?.[2]==='DOCUMENT'?'This value belongs only to this document draft.':'Editing here creates a document override. The canonical Shipment remains unchanged.'}</small>`};editable?.addEventListener('input',()=>{state[key]=editable.innerText.trim();dirty=true;buttons()});editable?.addEventListener('blur',()=>{if(state[key]!==history[cursor]?.[key])push()});editable?.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const next=fields[(idx+(e.shiftKey?-1:1)+fields.length)%fields.length];next.querySelector('[contenteditable]')?.focus();next.click()}})})};render()}
export async function mountShipmentDocumentStudio(host,s,preset=null){
 host.innerHTML='<div class="shipment-section-head"><div><h2>Documents</h2><p>Loading document workspace…</p></div></div>';
 const docs=SHIPMENT_DOCUMENT_CATALOG[s.mode]||SHIPMENT_DOCUMENT_CATALOG.GROUND;
 const [{data:issues},{data:compliance},{data:generated}]=await Promise.all([supabase.from('shipment_document_issues').select('*').eq('shipment_id',s.id).order('created_at',{ascending:false}),supabase.from('shipment_compliance_profiles').select('*').eq('shipment_id',s.id).maybeSingle(),supabase.from('documents').select('*').eq('source','GENERATED').contains('metadata',{shipment_id:s.id}).order('created_at',{ascending:false})]);
 const latest=new Map(),revisions=new Map();(issues||[]).forEach(x=>{if(!latest.has(x.document_code))latest.set(x.document_code,x);if(!revisions.has(x.document_code))revisions.set(x.document_code,[]);revisions.get(x.document_code).push(x)});const{data:instructionDocs}=await supabase.from('instruction_document_snapshots').select('*').eq('source_type','SHIPMENT').eq('source_id',s.id).order('created_at',{ascending:false});const finalInstruction=(instructionDocs||[]).find(x=>x.status==='FINAL');
 host.innerHTML=`<div class="shipment-section-head"><div><h2>Documents</h2><p>Work in Studio, create document drafts, and open generated revisions for viewing or printing.</p></div></div><div class="shipment-doc-control"><button class="primary" data-generate-selected disabled>Create selected drafts</button><span>${esc(s.mode)} · ${docs.length} document types</span><span>DG: ${esc(compliance?.dangerous_goods_status||'NOT DECLARED')}</span><span>Battery: ${esc(compliance?.lithium_battery_status||'NOT DECLARED')}</span></div>${(generated||[]).length?`<section class="nds-generated-register"><div class="nds-generated-head"><div><small>GENERATED FILES</small><h3>PDF revisions</h3></div><span>${generated.length} stored</span></div><div class="nds-generated-list">${generated.map(g=>`<article><div class="nds-generated-icon">PDF</div><div><b>${esc(g.display_name||g.file_name)}</b><small>${esc(g.document_type)} · ${new Date(g.created_at).toLocaleString()}</small></div><div><button data-generated-view="${g.id}">View</button><button data-generated-download="${g.id}">Download</button><button data-generated-share="${g.id}">Share</button></div></article>`).join('')}</div></section>`:''}<div class="shipment-doc-grid">${docs.map(d=>{const x=d.sourceManaged?finalInstruction:latest.get(d.code);const stale=!d.sourceManaged&&x?.source_stale;return `<article class="shipment-doc-card ${stale?'stale':''}"><label class="shipment-doc-select"><input type="checkbox" data-doc-select="${d.code}" ${d.sourceManaged?'disabled':preset===d.code?'checked':''}><span></span></label><small>${esc(d.group)} · ${esc(d.scope)}</small><h3>${esc(d.label)}</h3><p>${d.carrier?'Carrier-controlled master: prepare data/working copy.':d.controlled?'Controlled compliance document.':'Open the live document and edit its fields directly.'}</p><div><span>${x?(stale?'⚠ SOURCE CHANGED · ':'')+esc(x.status)+(d.sourceManaged?' · v'+x.version:' · R'+x.revision):'Not generated'}</span>${!d.sourceManaged&&revisions.get(d.code)?.length>1?`<button class="subtle" data-doc-history="${d.code}">${revisions.get(d.code).length} revisions</button>`:''}${d.sourceManaged?(x?'<button data-instruction-open>View approved</button>':'<button disabled>Approve instructions first</button>'):`${x?`<button data-doc-preview="${d.code}">View / Print</button>`:''}<button data-studio="${d.code}">${x?'Open Studio':'Create in Studio'}</button>`}</div></article>`}).join('')}</div>`;
 const generatedById=id=>(generated||[]).find(x=>x.id===id);const generatedUrl=async g=>{const{data,error}=await supabase.storage.from('nodara-documents').createSignedUrl(g.storage_path,600);if(error)throw error;return data.signedUrl};host.querySelectorAll('[data-generated-view]').forEach(b=>b.onclick=async()=>{try{window.open(await generatedUrl(generatedById(b.dataset.generatedView)),'_blank')}catch(e){alert(e.message)}});host.querySelectorAll('[data-generated-download]').forEach(b=>b.onclick=async()=>{try{const g=generatedById(b.dataset.generatedDownload),url=await generatedUrl(g),a=document.createElement('a');a.href=url;a.download=g.file_name||'document.pdf';a.target='_blank';a.click()}catch(e){alert(e.message)}});host.querySelectorAll('[data-generated-share]').forEach(b=>b.onclick=async()=>{try{const g=generatedById(b.dataset.generatedShare),url=await generatedUrl(g);if(navigator.share)await navigator.share({title:g.display_name||g.file_name,text:'Shipment document',url});else{await navigator.clipboard.writeText(url);alert('Secure document link copied. It expires in 10 minutes.')}}catch(e){if(e.name!=='AbortError')alert(e.message)}});
 const selected=()=>[...host.querySelectorAll('[data-doc-select]:checked')].map(x=>x.dataset.docSelect),bulk=host.querySelector('[data-generate-selected]');host.querySelectorAll('[data-doc-select]').forEach(x=>x.onchange=()=>{bulk.disabled=!selected().length;bulk.textContent=selected().length?`Create selected drafts · ${selected().length}`:'Create selected drafts'});bulk.disabled=!selected().length;bulk.textContent=selected().length?`Create selected drafts · ${selected().length}`:'Create selected drafts';bulk.onclick=async()=>{const codes=selected();if(!codes.length)return;bulk.disabled=true;try{for(const code of codes){const d=docs.find(x=>x.code===code);if(!latest.get(code))latest.set(code,await draft(d,s))}await mountShipmentDocumentStudio(host,s)}catch(e){alert(e.message)}};
 host.querySelectorAll('[data-doc-history]').forEach(b=>b.onclick=()=>{const d=docs.find(x=>x.code===b.dataset.docHistory),rows=revisions.get(d.code)||[];const old=host.querySelector('.nds-revision-drawer');old?.remove();const box=document.createElement('div');box.className='nds-revision-drawer';box.innerHTML='<div class="nds-revision-head"><div><small>DOCUMENT HISTORY</small><h3>'+esc(d.label)+'</h3></div><button data-close>×</button></div><div class="nds-revision-list">'+rows.map(x=>'<button data-rev="'+x.id+'"><span>R'+esc(x.revision)+' · '+esc(x.status)+'</span><small>'+esc(new Date(x.updated_at||x.created_at).toLocaleString())+'</small></button>').join('')+'</div>';host.appendChild(box);box.querySelector('[data-close]').onclick=()=>box.remove();box.querySelectorAll('[data-rev]').forEach(r=>r.onclick=()=>{const x=rows.find(v=>v.id===r.dataset.rev);if(x)printDoc(d,{...s,...(x.data_snapshot||{})},x)})});
 host.querySelectorAll('[data-doc-preview]').forEach(b=>b.onclick=()=>{const d=docs.find(x=>x.code===b.dataset.docPreview),x=latest.get(d.code);if(d&&x)printDoc(d,{...s,...(x.data_snapshot||{})},x)});
 host.querySelectorAll('[data-studio]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const d=docs.find(x=>x.code===b.dataset.studio);await openStudio(host,d,s,latest.get(d.code)||null)}catch(e){alert(e.message);b.disabled=false}});
 if(preset){const b=host.querySelector(`[data-studio="${preset}"]`);if(b)setTimeout(()=>b.click(),0)}
}
